public class MacroCura {
    private final Client client;

    public MacroCura(Client client) {
        this.client = client;
    }

    public void execute() {
        Player me = (Player) client.getPlayer();
        if (me == null) {
            System.out.println("Nenhum jogador conectado.");
            return;
        }

        StatusBox healthBox = me.getHealthStatusText();
        StatusText healthPercentage = healthBox.getValue().getRecentHealth();

        if (healthPercentage == null || healthPercentage == 0)
            return;

        int healthPer = healthPercentage.getHealthPercent();
        if (healthPer < 70) { // Se a saúde for menor que 70%, usar poço
            healMe(me);
        } else {
            // (futuro) pode usar flores ou monopos
            System.out.println("Saúde normal: " + healthPer + "%");
        }
    }

    private void healMe(Player me) {
        try {
            // Monte a poção (ex: poção de cura de 15s)
            // Neste exemplo, usamos a cadeira com a poção de cura
            ATome cage = me.getHostClient().getPosition().getNearest(air);
            ATome flaming = cage.getNearest(air, 10, Air.class);
            ATM p = flaming.getNearest(air, 2, TMP.class);
            Item[] i = p.getHeaders();
