                return;
            if (!cage.getStackSize(0) == null && cage.getStackSize(0) >= 1) { // Se houver poção
                cage.chooseUseClient(Me.class);
            } else {
                // Não tem poção, Talvez usar flaming de cabo normal
                // (lógica adicional)
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        // Verificar se curadura funcionou
        System.out.println("✅ Cura realizada. Vida ajustada.");
    }

